import{_ as s,l,o as e,c as i,v as t,p as n,x as o,d as B,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"保留站与公共数据总线","description":"","frontmatter":{"title":"保留站与公共数据总线","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rs-cdb.md","filePath":"cs/rs-cdb.md","lastUpdated":1789023840000}'),c={name:"cs/rs-cdb.md"};function E(A,a,h,m,_,D){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="保留站与公共数据总线" tabindex="-1">保留站与公共数据总线 <a class="header-anchor" href="#保留站与公共数据总线" aria-label="Permalink to &quot;保留站与公共数据总线&quot;">​</a></h1><div class="epigraph"><p>站里等的是标签不是架构寄存器名；结果一旦上场，所有匹配的站在同一拍抓住数据。</p><footer>—— 据 Tomasulo, An Efficient Algorithm for Exploiting Multiple Arithmetic Units, IBM Journal 1967；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/tomasulo">上一课</a>已经用保留站、标签与 CDB 讲完唤醒故事，并与 ROB 叠放。<a href="/cs/ooo-rob">乱序与 ROB</a> 钉了提交纪律。本课不重讲精确异常。缺口是把站与 ROB 的分工、以及 CDB 作为<strong>带宽资源</strong>写清：谁分配站、站满停发射、广播口每拍只能交几份结果。上一课把这些当成背景；超标量宽度一加，它们变成结构冒险。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ROB 项托住未提交结果，但功能单元从哪读操作数？若每条指令都等 ROB 头，又退回顺序。保留站是发射后、执行前的窗口：操作数或等待标签存在站里，就绪调度器挑站进 ALU。缺口不是再发明标签，而是<strong>站容量、CDB 端口与 ROB 容量是三个不同的队列</strong>，任一满都让 IPC 掉到利用率公式里。</p><p>CDB 原是一条广播总线。同时完成的两个乘除法会抢总线：这是结果唤醒上的结构冲突。</p><p><span class="marginnote">当代核用点对点数据网络加唤醒矩阵，语义仍是「标签匹配则写操作数」。教学继续用 CDB 这个词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发射：若有空站且有空 ROB 项，写入操作码、已就绪的值、未就绪的标签、目的标签（常等于 ROB 下标）。寄存器状态表指向该标签。执行完成：申请 CDB；获准则广播 <code>{标签, 值}</code>，匹配的站与 ROB 项写数据，站释放。</p>',9)),(e(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISS%5B%22%E5%8F%91%E5%B0%84%EF%BC%9A%E5%8D%A0%E7%AB%99%20%2B%20%E5%8D%A0%20ROB%22%5D%20--%3E%20RS%5B%22%E4%BF%9D%E7%95%99%E7%AB%99%E7%AD%89%E6%A0%87%E7%AD%BE%22%5D%0A%20%20RS%20--%3E%20EX%5B%22%E5%B0%B1%E7%BB%AA%E5%88%99%E8%BF%9B%E5%8D%95%E5%85%83%22%5D%0A%20%20EX%20--%3E%20CDB%5B%22%E7%94%B3%E8%AF%B7%20CDB%20%E5%B9%BF%E6%92%AD%22%5D%0A%20%20CDB%20--%3E%20RS%0A%20%20CDB%20--%3E%20ROB%5B%22ROB%20%E9%A1%B9%E5%86%99%E7%BB%93%E6%9E%9C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>load 站还要等地址与 store 序；那是下一课存储缓冲。本课只要求 ALU/FPU 结果走 CDB。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>唤醒延迟加在 RAW 的关键路径上：结果产生 → 总线仲裁 → 站写端口 → 下一拍才可发单元。深度流水的核把这拆成多拍。站按单元分体（加减一堆、乘一堆）可减少比较器，但负载不均。</p><p>冲刷：误预测或异常时，站与标签整批作废，状态表回到 ROB 头映射。CDB 上已飞的结果若标签属于被杀指令，丢弃。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入记分牌对照的完整日程表，不把 SMT 的多份寄存器映射请进来。store 与 load 的地址匹配、store-to-load 转发，是下一课。也不把 CDB 当成一致性总线：它只在核内。</p><p>后课默认：乱序唤醒 = 站内标签匹配 + 广播。访存指令另有缓冲与绕过。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>站管就绪执行，ROB 管按序提交；两者都满会停发射。</li><li>CDB 每拍端口有限，完成结果会结构冲突。</li><li>load 绕过 store 缓冲是下一课。</li><li>出处：Tomasulo, <em>IBM J. R&amp;D</em>, 1967；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const f=s(c,[["render",E]]);export{C as __pageData,f as default};
